/**
 * WORKING PDF PROCESSOR with OCR
 * 
 * Strategy:
 * 1. Try to extract text directly (for normal PDFs)
 * 2. If no text: Use Tesseract OCR (for scanned PDFs)
 * 3. If OCR fails: Manual entry
 */

import * as pdfjsLib from 'pdfjs-dist';
import Tesseract from 'tesseract.js';

// Configure PDF.js worker
pdfjsLib.GlobalWorkerOptions.workerSrc = `//cdnjs.cloudflare.com/ajax/libs/pdf.js/${pdfjsLib.version}/pdf.worker.min.js`;

/**
 * Perform OCR on a canvas using Tesseract
 */
async function performOCR(canvas, language = 'deu+eng', onProgress = null) {
    try {
        console.log('🔍 [OCR] Starting Tesseract OCR...');

        const { data } = await Tesseract.recognize(
            canvas,
            language,
            {
                logger: (m) => {
                    if (m.status === 'recognizing text') {
                        const progress = Math.round(m.progress * 100);
                        console.log(`🔍 [OCR] Progress: ${progress}%`);
                        if (onProgress) onProgress(progress);
                    }
                }
            }
        );

        console.log(`✅ [OCR] Confidence: ${data.confidence.toFixed(1)}%`);
        console.log(`✅ [OCR] Extracted: ${data.text.length} characters`);

        return data.text;
    } catch (error) {
        console.error('❌ [OCR] Error:', error);
        return '';
    }
}

/**
 * Extract ALL text from PDF with OCR fallback
 */
export async function extractTextFromPDF(file, progressCallback) {
    try {
        console.log('🚀 [PDF PROCESSOR v2.3.0] Starting...');
        console.log('📄 [PDF PROCESSOR] File:', file.name, `(${(file.size / 1024 / 1024).toFixed(2)} MB)`);

        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

        const totalPages = pdf.numPages;
        console.log(`📚 [PDF PROCESSOR] Total pages: ${totalPages}`);

        // STEP 1: Try direct text extraction first
        let fullText = '';
        let totalItems = 0;

        console.log('📝 [STEP 1] Trying direct text extraction...');

        for (let pageNum = 1; pageNum <= totalPages; pageNum++) {
            if (progressCallback) {
                progressCallback({
                    status: 'extracting',
                    page: pageNum,
                    totalPages: totalPages,
                    percentage: Math.round((pageNum / totalPages) * 100)
                });
            }

            try {
                const page = await pdf.getPage(pageNum);
                const textContent = await page.getTextContent();

                console.log(`📄 [PAGE ${pageNum}] Raw items: ${textContent.items.length}`);
                totalItems += textContent.items.length;

                const textItems = textContent.items
                    .map(item => (item.str || '').trim())
                    .filter(text => text.length > 0);

                const pageText = textItems.join(' ');
                console.log(`📄 [PAGE ${pageNum}] Extracted: ${pageText.length} chars`);
                console.log(`📄 [PAGE ${pageNum}] Sample: "${pageText.substring(0, 150)}"`);

                if (pageText.length > 0) {
                    fullText += pageText + '\n\n';
                }
            } catch (pageError) {
                console.error(`❌ [PAGE ${pageNum}] Error:`, pageError);
            }
        }

        const totalChars = fullText.trim().length;
        console.log(`\n📊 [DIRECT EXTRACTION RESULT]`);
        console.log(`   ✓ Total items found: ${totalItems}`);
        console.log(`   ✓ Total characters: ${totalChars}`);
        console.log(`   ✓ Threshold: 20 characters (VERY LOW)`);
        console.log(`   ✓ Full text preview (first 500 chars):\n"${fullText.substring(0, 500)}"\n`);
        console.log(`   ✓ Full text preview (last 200 chars):\n"${fullText.substring(Math.max(0, fullText.length - 200))}"\n`);

        // VERY LOW threshold - accept almost anything
        if (totalChars >= 20) {
            console.log(`✅ [PDF PROCESSOR] SUCCESS - Text extracted directly! (${totalChars} chars)`);
            console.log(`✅ [PDF PROCESSOR] Returning trimmed text: ${fullText.trim().length} chars`);
            return fullText.trim();
        }

        console.log(`❌ [PDF PROCESSOR] Direct extraction failed: only ${totalChars} chars (need 20+)`);

        // STEP 2: Not enough text - try OCR
        console.log('⚠️ [PDF PROCESSOR] Not enough text - trying OCR...');
        console.log('� [PDF PROCESSOR] Processing first 3 pages with OCR...');

        fullText = '';
        const pagesToOCR = Math.min(3, totalPages);

        for (let pageNum = 1; pageNum <= pagesToOCR; pageNum++) {
            if (progressCallback) {
                progressCallback({
                    status: 'ocr',
                    page: pageNum,
                    totalPages: pagesToOCR,
                    percentage: Math.round((pageNum / pagesToOCR) * 100),
                    ocrProgress: 0
                });
            }

            try {
                const page = await pdf.getPage(pageNum);

                // Render at high quality
                const viewport = page.getViewport({ scale: 3.0 });
                const canvas = document.createElement('canvas');
                const context = canvas.getContext('2d');
                canvas.width = viewport.width;
                canvas.height = viewport.height;

                await page.render({
                    canvasContext: context,
                    viewport: viewport
                }).promise;

                console.log(`� [PAGE ${pageNum}] Running OCR...`);

                const ocrText = await performOCR(canvas, 'deu+eng', (ocrProgress) => {
                    if (progressCallback) {
                        progressCallback({
                            status: 'ocr',
                            page: pageNum,
                            totalPages: pagesToOCR,
                            percentage: Math.round((pageNum / pagesToOCR) * 100),
                            ocrProgress: ocrProgress
                        });
                    }
                });

                if (ocrText.length > 0) {
                    fullText += ocrText + '\n\n';
                    console.log(`✅ [PAGE ${pageNum}] OCR extracted ${ocrText.length} characters`);
                }
            } catch (pageError) {
                console.error(`❌ [PAGE ${pageNum}] OCR Error:`, pageError);
            }
        }

        const ocrChars = fullText.trim().length;
        console.log(`\n📊 [OCR FINAL RESULT]`);
        console.log(`   ✓ Characters extracted: ${ocrChars}`);
        console.log(`   ✓ Threshold: 20 characters (VERY LOW)`);
        console.log(`   ✓ Text preview:\n"${fullText.substring(0, 300)}"\n`);

        // VERY LOW threshold - accept almost anything
        if (ocrChars >= 20) {
            console.log('✅ [PDF PROCESSOR] SUCCESS - OCR extracted text!');
            return fullText.trim();
        } else {
            console.log('⚠️ [PDF PROCESSOR] OCR failed - needs manual entry');
            console.log(`   ✗ Only got ${ocrChars} characters (need 20+)`);
            return null;
        }

    } catch (error) {
        console.error('❌ [PDF PROCESSOR] FATAL ERROR:', error);
        throw error;
    }
}

/**
 * Generate PDF previews for manual entry
 */
export async function generatePDFPreviews(file, maxPages = 3) {
    try {
        console.log('🖼️ [PREVIEW] Generating previews...');

        const arrayBuffer = await file.arrayBuffer();
        const pdf = await pdfjsLib.getDocument({ data: arrayBuffer }).promise;

        const previews = [];
        const pagesToRender = Math.min(maxPages, pdf.numPages);

        for (let pageNum = 1; pageNum <= pagesToRender; pageNum++) {
            const page = await pdf.getPage(pageNum);

            // Render at good quality
            const viewport = page.getViewport({ scale: 2.0 });
            const canvas = document.createElement('canvas');
            const context = canvas.getContext('2d');
            canvas.width = viewport.width;
            canvas.height = viewport.height;

            await page.render({
                canvasContext: context,
                viewport: viewport
            }).promise;

            previews.push({
                pageNum: pageNum,
                dataUrl: canvas.toDataURL('image/png'),
                width: viewport.width,
                height: viewport.height
            });

            console.log(`✅ [PREVIEW] Generated page ${pageNum}`);
        }

        console.log(`✅ [PREVIEW] Done - ${previews.length} previews generated`);

        return {
            previews: previews,
            totalPages: pdf.numPages,
            hasMorePages: pdf.numPages > maxPages
        };
    } catch (error) {
        console.error('❌ [PREVIEW] Error:', error);
        throw error;
    }
}
