/**
 * SMART Question Generator v3.0
 * Generates high-quality, context-aware questions
 */

/**
 * Clean and prepare text
 */
function prepareText(text) {
    return text
        .replace(/\s+/g, ' ')
        .replace(/\n+/g, ' ')
        .trim();
}

/**
 * Split into sentences with better logic
 */
function extractSentences(text) {
    const prepared = prepareText(text);

    // Split on sentence endings AND newlines for better flexibility
    const sentences = prepared
        .split(/(?<=[.!?])\s+|[\n]+/)
        .map(s => s.trim())
        .filter(s => {
            const wordCount = s.split(/\s+/).length;
            // RELAXED: Accept sentences with 3+ words and 15+ chars
            return s.length >= 15 && wordCount >= 3;
        });

    console.log(`📝 Extracted ${sentences.length} valid sentences (relaxed criteria: 15+ chars, 3+ words)`);
    return sentences;
}

/**
 * Extract important words/terms
 */
function extractImportantWords(text) {
    // Common words to ignore
    const stopWords = new Set([
        'der', 'die', 'das', 'den', 'dem', 'des', 'ein', 'eine', 'einen',
        'und', 'oder', 'aber', 'auch', 'wenn', 'dann', 'als', 'wie', 'was',
        'von', 'zu', 'mit', 'bei', 'nach', 'für', 'auf', 'durch', 'über',
        'ist', 'sind', 'war', 'hat', 'wird', 'kann', 'soll', 'muss',
        'the', 'be', 'to', 'of', 'and', 'in', 'that', 'have', 'for',
        'not', 'on', 'with', 'as', 'you', 'do', 'at', 'this', 'but',
        'his', 'by', 'from', 'they', 'we', 'or', 'an', 'will', 'would'
    ]);

    const words = prepareText(text.toLowerCase())
        .split(/\s+/)
        .map(w => w.replace(/[^\wäöüß]/g, ''))
        .filter(w => w.length >= 4 && !stopWords.has(w));

    // Count frequencies
    const freq = {};
    words.forEach(w => freq[w] = (freq[w] || 0) + 1);

    // Return top words sorted by frequency
    const important = Object.entries(freq)
        .sort((a, b) => b[1] - a[1])
        .slice(0, 40)
        .map(([word]) => word);

    console.log(`🔑 Found ${important.length} important words:`, important.slice(0, 10));
    return important;
}

/**
 * Generate Fill-in-the-Blank Questions (IMPROVED)
 */
function generateFillBlanks(sentences, importantWords, count) {
    const questions = [];
    const used = new Set();

    for (const sentence of sentences) {
        if (questions.length >= count) break;
        if (used.has(sentence)) continue;

        const words = sentence.split(/\s+/);
        if (words.length < 3) continue; // Skip very short sentences

        // Find the BEST word to blank out
        let bestWord = null;
        let bestIndex = -1;
        let bestScore = 0;

        for (let i = 0; i < words.length; i++) {
            const word = words[i].replace(/[^\wäöüß]/gi, '');
            const lower = word.toLowerCase();

            // RELAXED: Accept 3+ char words (was 4+)
            if (word.length < 3 || word.length > 20) continue;

            // Calculate score based on importance and position
            const isImportant = importantWords.includes(lower);
            const middlePosition = Math.abs(i - words.length / 2) / words.length;
            const score = (isImportant ? 10 : 1) * (1 - middlePosition);

            if (score > bestScore) {
                bestScore = score;
                bestWord = word;
                bestIndex = i;
            }
        }

        if (bestWord && bestIndex >= 0) {
            const questionWords = [...words];
            questionWords[bestIndex] = '______';

            questions.push({
                id: `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                type: 'fill-blank',
                question: questionWords.join(' '),
                answer: bestWord.replace(/[^\wäöüß]/gi, ''),
                points: 10
            });

            used.add(sentence);
        }
    }

    console.log(`✅ Generated ${questions.length} fill-blank questions`);
    return questions;
}

/**
 * Generate Multiple Choice Questions (IMPROVED)
 */
function generateMultipleChoice(sentences, importantWords, count) {
    const questions = [];
    const used = new Set();

    for (const sentence of sentences) {
        if (questions.length >= count) break;
        if (used.has(sentence)) continue;

        const words = sentence.split(/\s+/);

        // Find important word (RELAXED: 4+ chars instead of 5+)
        let targetWord = null;
        let targetIndex = -1;

        for (let i = 0; i < words.length; i++) {
            const word = words[i].replace(/[^\wäöüß]/gi, '');
            const lower = word.toLowerCase();

            if (importantWords.includes(lower) && word.length >= 4) {
                targetWord = word;
                targetIndex = i;
                break;
            }
        }

        // FALLBACK: If no important word, just pick any word 5+ chars
        if (!targetWord) {
            for (let i = 0; i < words.length; i++) {
                const word = words[i].replace(/[^\wäöüß]/gi, '');
                if (word.length >= 5) {
                    targetWord = word;
                    targetIndex = i;
                    break;
                }
            }
        }

        if (!targetWord) continue;

        const correct = targetWord.replace(/[^\wäöüß]/gi, '');

        // Generate plausible wrong answers
        const wrongAnswers = [];

        // Use other important words as distractors
        for (const iw of importantWords) {
            if (iw !== correct.toLowerCase() && iw.length >= 4) {
                wrongAnswers.push(iw.charAt(0).toUpperCase() + iw.slice(1));
            }
            if (wrongAnswers.length >= 3) break;
        }

        // Fill up if needed
        while (wrongAnswers.length < 3) {
            wrongAnswers.push(`${String.fromCharCode(65 + wrongAnswers.length)}ntwort ${wrongAnswers.length + 1}`);
        }

        const questionWords = [...words];
        questionWords[targetIndex] = '___';

        const allOptions = [correct, ...wrongAnswers].sort(() => Math.random() - 0.5);

        questions.push({
            id: `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            type: 'multiple-choice',
            question: questionWords.join(' '),
            options: allOptions,
            correctAnswer: correct,
            points: 10
        });

        used.add(sentence);
    }

    console.log(`✅ Generated ${questions.length} multiple-choice questions`);
    return questions;
}

/**
 * Generate True/False Questions (IMPROVED)
 */
function generateTrueFalse(sentences, importantWords, count) {
    const questions = [];
    const used = new Set();

    for (const sentence of sentences) {
        if (questions.length >= count) break;
        if (used.has(sentence)) continue;

        // True statement
        questions.push({
            id: `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
            type: 'true-false',
            question: sentence,
            correctAnswer: 'Wahr',
            points: 5
        });

        used.add(sentence);
        if (questions.length >= count) break;

        // Try to create a false statement
        const words = sentence.split(/\s+/);
        let modified = null;

        // Strategy 1: Swap an important word
        for (let i = 0; i < words.length; i++) {
            const word = words[i].replace(/[^\wäöüß]/gi, '');
            const lower = word.toLowerCase();

            if (importantWords.includes(lower) && word.length >= 5) {
                // Find a different important word
                const replacement = importantWords.find(iw =>
                    iw !== lower &&
                    iw.length >= 5 &&
                    iw.length <= word.length + 3
                );

                if (replacement) {
                    const modWords = [...words];
                    modWords[i] = replacement.charAt(0).toUpperCase() + replacement.slice(1);
                    modified = modWords.join(' ');
                    break;
                }
            }
        }

        // Strategy 2: Negate if possible
        if (!modified) {
            if (sentence.includes(' ist ')) {
                modified = sentence.replace(' ist ', ' ist nicht ');
            } else if (sentence.includes(' sind ')) {
                modified = sentence.replace(' sind ', ' sind nicht ');
            } else if (sentence.includes(' kann ')) {
                modified = sentence.replace(' kann ', ' kann nicht ');
            }
        }

        if (modified && modified !== sentence) {
            questions.push({
                id: `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                type: 'true-false',
                question: modified,
                correctAnswer: 'Falsch',
                points: 5
            });
        }
    }

    console.log(`✅ Generated ${questions.length} true-false questions`);
    return questions;
}

/**
 * Generate Short Answer Questions (IMPROVED)
 */
function generateShortAnswer(sentences, importantWords, count) {
    const questions = [];
    const used = new Set();

    const questionTemplates = [
        (word) => `Was bedeutet "${word}"?`,
        (word) => `Erkläre den Begriff "${word}".`,
        (word) => `Definiere "${word}".`,
        (word) => `Was versteht man unter "${word}"?`,
        (word) => `Beschreibe "${word}".`
    ];

    for (const sentence of sentences) {
        if (questions.length >= count) break;
        if (used.has(sentence)) continue;

        const words = sentence.split(/\s+/);

        // Find the most important word
        let bestWord = null;
        let bestRank = -1;

        for (const word of words) {
            const cleaned = word.replace(/[^\wäöüß]/gi, '');
            const lower = cleaned.toLowerCase();
            const rank = importantWords.indexOf(lower);

            if (rank >= 0 && rank < 20 && cleaned.length >= 5 && (bestRank === -1 || rank < bestRank)) {
                bestWord = cleaned;
                bestRank = rank;
            }
        }

        if (bestWord) {
            const template = questionTemplates[Math.floor(Math.random() * questionTemplates.length)];

            questions.push({
                id: `q-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`,
                type: 'short-answer',
                question: template(bestWord),
                answer: bestWord,
                points: 15,
                context: sentence
            });

            used.add(sentence);
        }
    }

    console.log(`✅ Generated ${questions.length} short-answer questions`);
    return questions;
}

/**
 * MAIN FUNCTION - Generate Questions
 */
export function generateQuestions(text, totalCount = 10) {
    console.log('\n🎓 [SMART QUESTION GENERATOR v3.0] Starting...');
    console.log(`📄 Input: ${text.length} characters`);
    console.log(`🎯 Requested: ${totalCount} questions`);

    if (!text || text.length < 50) {
        throw new Error('❌ Text zu kurz! Mindestens 50 Zeichen benötigt.');
    }

    // Extract content
    const sentences = extractSentences(text);
    const importantWords = extractImportantWords(text);

    console.log(`📊 Extracted: ${sentences.length} sentences, ${importantWords.length} key terms`);

    // FALLBACK: If not enough sentences, split by any punctuation or newlines
    if (sentences.length < 2) {
        console.log('⚠️ Not enough sentences with strict criteria, trying fallback...');
        const fallbackSentences = text
            .split(/[.!?\n]+/)
            .map(s => s.trim())
            .filter(s => s.length >= 10 && s.split(/\s+/).length >= 2);

        console.log(`📝 Fallback extracted ${fallbackSentences.length} segments`);

        if (fallbackSentences.length < 2) {
            throw new Error('❌ Nicht genug Inhalt gefunden. Bitte mehr Text bereitstellen (mindestens ein paar Sätze).');
        }

        sentences.push(...fallbackSentences);
    }

    console.log(`\n📊 Analysis:`);
    console.log(`   - Sentences: ${sentences.length}`);
    console.log(`   - Key terms: ${importantWords.length}`);

    // Shuffle sentences for variety
    const shuffled = sentences.sort(() => Math.random() - 0.5);

    // Distribute question types (request MORE than needed to ensure we get enough)
    const requestMultiplier = 1.5; // Request 50% more to account for generation failures
    const dist = {
        fillBlank: Math.ceil(totalCount * 0.35 * requestMultiplier),
        multipleChoice: Math.ceil(totalCount * 0.30 * requestMultiplier),
        trueFalse: Math.ceil(totalCount * 0.25 * requestMultiplier),
        shortAnswer: Math.ceil(totalCount * 0.10 * requestMultiplier)
    };

    console.log(`\n📊 Distribution (requesting extra to ensure quality):`, dist);

    // Generate questions
    const allQuestions = [
        ...generateFillBlanks(shuffled, importantWords, dist.fillBlank),
        ...generateMultipleChoice(shuffled, importantWords, dist.multipleChoice),
        ...generateTrueFalse(shuffled, importantWords, dist.trueFalse),
        ...generateShortAnswer(shuffled, importantWords, dist.shortAnswer)
    ];

    console.log(`\n📊 Generated ${allQuestions.length} total questions (before filtering)`);

    // Shuffle and limit
    const final = allQuestions
        .sort(() => Math.random() - 0.5)
        .slice(0, totalCount);

    console.log(`\n✅ Generated ${final.length} high-quality questions!`);
    console.log(`📊 Final distribution:`, {
        'Fill Blank': final.filter(q => q.type === 'fill-blank').length,
        'Multiple Choice': final.filter(q => q.type === 'multiple-choice').length,
        'True/False': final.filter(q => q.type === 'true-false').length,
        'Short Answer': final.filter(q => q.type === 'short-answer').length
    });

    if (final.length === 0) {
        throw new Error('❌ Konnte keine Fragen generieren. Der Text ist eventuell zu kurz oder enthält nicht genug verwertbaren Inhalt.');
    }

    // If we have fewer questions than requested, that's OK - return what we have
    if (final.length < totalCount) {
        console.log(`⚠️ Generated ${final.length} questions (requested ${totalCount}) - limited by available content`);
    }

    return final;
}
